import { ShipperBooking } from "../types/bookingOverview";

export interface BookingDetail {
  id: string;
  customer: string;
  carrier: string;
  carrierBookingNumber: string;
  region: string;
  status: string;
  statusLevel: number;
  placeOfReceipt: string;
  portOfLoad: string;
  portOfDischarge: string;
  placeOfDelivery: string;
  equipments: string;
  crd: string;
  moveType: string;
  placeOfReceiptEtd: string;
  portOfLoadEtd: string;
  portOfDischargeEta: string;
  placeOfDeliveryEta: string;
  requestedEtdWeek: string;
  contractNumber: string;
  tradeLane: string;
  vesselNVoyage: string;
  exception: boolean;
}

export interface CarrierBooking {
  id: string;
  destination: string;
  date: string;
  selected?: boolean;
}

export interface LinkedBooking {
  id: string;
  shipper_bkg_no: string;
  crd_date: string;
  consignee: string;
  shipWindow: string;
}

export interface ActivityItem {
  id: string;
  type: 'pending' | 'secondary' | 'exception' | 'confirmed' | 'accepted' | 'linked' | 'approved' | 'submitted' | 'departed' | 'arrived' | 'delayed' | 'cutoff' | 'loaded' | 'eta' | 'delivered' | 'etd_change' | 'equipment_mismatch';
  title: string;
  description: string;
  date: string;
  details?: string;
  severity: 'info' | 'success' | 'warning' | 'error' | 'high';
  highlight: boolean;
  tags: string[];
  reqETD?: string;
  createDate?: string;
}

export interface DocumentItem {
  id: string;
  tmsId: string;
  pdfRevision: string;
  pdfLink: string;
  uploadDate: string;
  fileSize: string;
}


